create extension if not exists pg_trgm;

create table if not exists brands (id bigint generated always as identity primary key, slug text not null unique, name text not null, website text, logo_url text, description text, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table if not exists categories (id bigint generated always as identity primary key, parent_id bigint references categories(id), slug text not null unique, name text not null, description text);
create table if not exists products (id bigint generated always as identity primary key, slug text not null unique, brand_id bigint references brands(id), model text, title text not null, description text, category_id bigint references categories(id), capacity_quart numeric, capacity_liters numeric, wattage integer, basket_type text, basket_count integer, dishwasher_safe boolean, rotisserie boolean, digital_controls boolean, temperature_min integer, temperature_max integer, dimensions jsonb, weight numeric, release_date date, status text not null default 'active', lifecycle_state text not null default 'draft', created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table if not exists product_identifiers (id bigint generated always as identity primary key, product_id bigint not null references products(id) on delete cascade, identifier_type text not null, identifier_value text not null, country text, source text, verified boolean not null default false, created_at timestamptz not null default now(), unique(identifier_type, identifier_value));
create table if not exists product_features (id bigint generated always as identity primary key, product_id bigint not null references products(id) on delete cascade, feature_key text not null, feature_value text, source text, verified boolean not null default false);
create table if not exists data_sources (id bigint generated always as identity primary key, name text not null unique, type text, api_endpoint text, terms_url text, rate_limit text, commercial_use boolean, last_sync_at timestamptz);
create table if not exists data_licenses (id bigint generated always as identity primary key, source_id bigint not null references data_sources(id) on delete cascade, license_type text not null, redistribution_allowed boolean not null default false, caching_allowed boolean not null default false, image_reuse_allowed boolean not null default false, attribution_required boolean not null default false, attribution_text text, expires_at timestamptz, verified_by text, verified_at timestamptz);
create table if not exists retailers (id bigint generated always as identity primary key, name text not null, domain text not null unique, country text, affiliate_program text, affiliate_status text);
create table if not exists product_retailers (id bigint generated always as identity primary key, product_id bigint not null references products(id) on delete cascade, retailer_id bigint not null references retailers(id), external_product_id text, url text, affiliate_url text, price numeric, currency text, availability text, last_checked_at timestamptz);
create table if not exists comparisons (id bigint generated always as identity primary key, slug text not null unique, product_a_id bigint not null references products(id), product_b_id bigint not null references products(id), status text not null default 'draft', search_demand numeric, quality_score numeric, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), check(product_a_id <> product_b_id));
create table if not exists use_cases (id bigint generated always as identity primary key, slug text not null unique, name text not null, description text);
create table if not exists product_use_cases (product_id bigint not null references products(id) on delete cascade, use_case_id bigint not null references use_cases(id) on delete cascade, match_score numeric, evidence text, primary key(product_id, use_case_id));
create table if not exists keywords (id bigint generated always as identity primary key, keyword text not null, normalized_keyword text not null unique, intent text, volume numeric, country text, language text default 'en', source text, last_updated_at timestamptz);
create table if not exists keyword_pages (keyword_id bigint not null references keywords(id) on delete cascade, page_type text not null, page_id bigint, status text not null default 'draft', primary key(keyword_id, page_type, page_id));
create table if not exists ingestion_jobs (id bigint generated always as identity primary key, source_id bigint references data_sources(id), job_type text not null, status text not null, started_at timestamptz, completed_at timestamptz, records_processed integer default 0, records_created integer default 0, records_updated integer default 0, records_failed integer default 0, error_log text);
create index if not exists products_model_idx on products(model);
create index if not exists products_brand_idx on products(brand_id);
create index if not exists products_category_idx on products(category_id);
create index if not exists product_identifiers_value_idx on product_identifiers(identifier_value);
create index if not exists product_retailers_product_idx on product_retailers(product_id);
create index if not exists keywords_normalized_idx on keywords(normalized_keyword);
create index if not exists comparisons_a_idx on comparisons(product_a_id);
create index if not exists comparisons_b_idx on comparisons(product_b_id);
create index if not exists products_title_trgm_idx on products using gin (title gin_trgm_ops);
